import { ChevronRight, Download } from 'lucide-react';
import type { Experience } from '@/features/profile';
import { Container, SectionDisplayHeading } from '@/shared/ui';
import { toExperienceRow } from '../model';

type ExperienceSectionProps = {
  experience: Experience[];
  experienceSummary: string;
  /** PDF generated by story 2.5 (architecture D4). */
  cvHref: string;
  /** File name the browser saves the PDF under (`download` attribute). */
  cvFileName: string;
};

const HEADING_ID = 'experience-heading';

/** `#experience`: one row per position (date range + Current/duration, company, role). */
export function ExperienceSection({
  experience,
  experienceSummary,
  cvHref,
  cvFileName,
}: ExperienceSectionProps) {
  const rows = experience.map(toExperienceRow);

  return (
    <section id="experience" aria-labelledby={HEADING_ID} className="scroll-mt-20 py-20">
      <Container>
        <SectionDisplayHeading id={HEADING_ID}>Experience</SectionDisplayHeading>
        <div className="mt-6 flex justify-end">
          <a
            href={cvHref}
            download={cvFileName}
            className="inline-flex h-9 items-center gap-2 rounded-md border border-input bg-background px-3 font-mono text-sm text-foreground transition-colors duration-150 hover:bg-accent hover:text-accent-foreground"
          >
            <Download aria-hidden="true" size={16} />
            Download CV
          </a>
        </div>

        <ul className="mt-16 space-y-3">
          {rows.map((row) => (
            <li
              key={`${row.company}-${row.dateRange}`}
              className="group relative grid gap-2 overflow-hidden rounded-2xl bg-card/60 p-8 transition-colors duration-150 after:absolute after:inset-x-0 after:bottom-0 after:h-1 after:bg-accent after:opacity-0 after:transition-opacity hover:bg-card hover:after:opacity-100 md:grid-cols-12 md:items-center md:gap-6"
            >
              <div className="md:col-span-3">
                <p className="font-mono text-sm font-bold text-foreground">{row.dateRange}</p>
                <p className="text-xs text-muted-foreground">{row.detail}</p>
              </div>
              <p className="font-mono text-xl font-bold text-foreground transition-colors duration-150 group-hover:text-accent md:col-span-4 md:text-base">
                {row.company}
              </p>
              <p className="font-mono text-sm text-muted-foreground md:col-span-5 md:flex md:items-center md:justify-between">
                {row.role}
                <ChevronRight
                  aria-hidden="true"
                  size={16}
                  className="hidden opacity-0 transition-opacity group-hover:opacity-100 md:block"
                />
              </p>
            </li>
          ))}
        </ul>

        <div className="mt-8 text-right">
          <p className="text-xs text-muted-foreground">Professional summary</p>
          <p className="mt-1 font-mono text-lg font-semibold text-foreground md:text-2xl">
            {experienceSummary}
          </p>
        </div>
      </Container>
    </section>
  );
}
